contracts/CMPX.sol.content:
// SPDX-License-Identifier: MIT
// ComplicesConecta v3.7.0 - Token CMPX (Utility)
// Fecha: 13 Nov 2025 | Autor: Ing. Juan Carlos Méndez Nataren
// Descripción: Token ERC-20 upgradeable con seguridad extrema para ComplicesConecta
// Funcionalidades: ReentrancyGuard, blacklist, max supply, mint controlado

pragma solidity ^0.8.25;

import "@openzeppelin/contracts-upgradeable/token/ERC20/ERC20Upgradeable.sol";
import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/security/ReentrancyGuardUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/security/PausableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";

/**
 * @title CMPX Token - ComplicesConecta Utility Token
 * @dev Token ERC-20 para el ecosistema ComplicesConecta
 * @notice Token principal para mint de NFTs, staking y economía interna
 * 
 * Características principales:
 * - Supply máximo: 1,000,000,000 CMPX (1B)
 * - Upgradeable para futuras mejoras
 * - Sistema de blacklist para seguridad
 * - ReentrancyGuard para prevenir ataques
 * - Pausable para emergencias
 * - Mint controlado solo por owner
 */
contract CMPX is 
    Initializable,
    ERC20Upgradeable, 
    OwnableUpgradeable, 
    ReentrancyGuardUpgradeable,
    PausableUpgradeable 
{
    /// @notice Supply máximo de tokens CMPX (1.25 billones - incluye 25% para testing)
    uint256 public constant MAX_SUPPLY = 1_250_000_000 * 10**18;

    /// @notice Mapping de direcciones en blacklist
    mapping(address => bool) public blacklisted;

    /// @notice Mapping de direcciones autorizadas para mint
    mapping(address => bool) public minters;

    /// @notice Total de tokens mintados hasta ahora
    uint256 public totalMinted;

    /// @notice Indica si el contrato está en modo testnet
    bool public isTestnet;

    /// @notice Pool de tokens para testing (25% del supply)
    uint256 public constant TESTNET_POOL = 250_000_000 * 10**18;

    /// @notice Tokens distribuidos para testing
    uint256 public testnetTokensDistributed;

    /// @notice Límite de tokens gratuitos por usuario en testnet
    uint256 public constant TESTNET_FREE_LIMIT = 1000 * 10**18; // 1000 CMPX por usuario

    /// @notice Límite diario del 1% del pool de testnet por usuario registrado
    uint256 public constant DAILY_CLAIM_LIMIT = TESTNET_POOL / 100; // 1% del pool = 2.5M CMPX

    /// @notice Mapping de tokens gratuitos reclamados por usuario en testnet
    mapping(address => uint256) public testnetTokensClaimed;

    /// @notice Mapping de último reclamo diario por usuario
    mapping(address => uint256) public lastDailyClaim;

    /// @notice Mapping de tokens reclamados hoy por usuario
    mapping(address => uint256) public dailyTokensClaimed;

    // Eventos personalizados
    event AddressBlacklisted(address indexed account, bool status);
    event MinterAdded(address indexed minter);
    event MinterRemoved(address indexed minter);
    event TokensMinted(address indexed to, uint256 amount, string reason);
    event TestnetTokensClaimed(address indexed user, uint256 amount);
    event DailyTokensClaimed(address indexed user, uint256 amount, uint256 day);
    event TestnetModeToggled(bool isTestnet);

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    /**
     * @notice Inicializa el contrato CMPX
     * @param initialOwner Dirección del propietario inicial
     * @param _isTestnet Si el contrato está en modo testnet
     */
    function initialize(address initialOwner, bool _isTestnet) external initializer {
        require(initialOwner != address(0), "CMPX: Owner cannot be zero address");

        __ERC20_init("ComplicesConecta CMPX", "CMPX");
        __Ownable_init();
        _transferOwnership(initialOwner);
        __ReentrancyGuard_init();
        __Pausable_init();

        // Configurar modo testnet
        isTestnet = _isTestnet;

        // Mint inicial al owner (distribución según tokenomics)
        uint256 initialMint = MAX_SUPPLY * 60 / 100; // 60% para distribución inicial
        _mint(initialOwner, initialMint);
        totalMinted = initialMint;

        emit TokensMinted(initialOwner, initialMint, "Initial distribution");
        emit TestnetModeToggled(_isTestnet);
    }

    /**
     * @notice Transfiere tokens con verificaciones de seguridad
     * @param to Dirección destino
     * @param amount Cantidad a transferir
     * @return bool Éxito de la operación
     */
    function transfer(address to, uint256 amount) 
        public 
        override 
        nonReentrant 
        whenNotPaused 
        returns (bool) 
    {
        require(!blacklisted[msg.sender], "CMPX: Sender is blacklisted");
        require(!blacklisted[to], "CMPX: Recipient is blacklisted");
        require(to != address(0), "CMPX: Transfer to zero address");

        return super.transfer(to, amount);
    }

    /**
     * @notice Transfiere tokens desde una dirección con verificaciones de seguridad
     * @param from Dirección origen
     * @param to Dirección destino
     * @param amount Cantidad a transferir
     * @return bool Éxito de la operación
     */
    function transferFrom(address from, address to, uint256 amount) 
        public 
        override 
        nonReentrant 
        whenNotPaused 
        returns (bool) 
    {
        require(!blacklisted[from], "CMPX: From address is blacklisted");
        require(!blacklisted[to], "CMPX: To address is blacklisted");
        require(to != address(0), "CMPX: Transfer to zero address");

        return super.transferFrom(from, to, amount);
    }

    /**
     * @notice Mintea tokens nuevos (solo minters autorizados)
     * @param to Dirección destino
     * @param amount Cantidad a mintear
     * @param reason Razón del mint para auditoría
     */
    function mint(address to, uint256 amount, string calldata reason) 
        external 
        nonReentrant 
        whenNotPaused 
    {
        require(minters[msg.sender] || msg.sender == owner(), "CMPX: Not authorized to mint");
        require(to != address(0), "CMPX: Mint to zero address");
        require(!blacklisted[to], "CMPX: Cannot mint to blacklisted address");
        require(totalMinted + amount <= MAX_SUPPLY, "CMPX: Exceeds max supply");

        _mint(to, amount);
        totalMinted += amount;

        emit TokensMinted(to, amount, reason);
    }

    /**
     * @notice Mintea tokens para conversión de Tokens Premium (solo owner)
     * @param user Dirección del usuario
     * @param tpAmount Cantidad de Tokens Premium a convertir
     */
    function mintForPremium(address user, uint256 tpAmount) 
        external 
        onlyOwner 
        nonReentrant 
        whenNotPaused 
    {
        require(user != address(0), "CMPX: User cannot be zero address");
        require(!blacklisted[user], "CMPX: User is blacklisted");
        require(tpAmount >= 1000, "CMPX: Minimum 1000 TP required");

        uint256 cmpxAmount = tpAmount / 10; // 10 TP = 1 CMPX
        require(totalMinted + cmpxAmount <= MAX_SUPPLY, "CMPX: Exceeds max supply");

        _mint(user, cmpxAmount);
        totalMinted += cmpxAmount;

        emit TokensMinted(user, cmpxAmount, "Premium conversion");
    }

    /**
     * @notice Añade o remueve una dirección de la blacklist (solo owner)
     * @param account Dirección a modificar
     * @param status true para blacklist, false para remover
     */
    function setBlacklist(address account, bool status) external onlyOwner {
        require(account != address(0), "CMPX: Cannot blacklist zero address");
        require(account != owner(), "CMPX: Cannot blacklist owner");

        blacklisted[account] = status;
        emit AddressBlacklisted(account, status);
    }

    /**
     * @notice Añade un minter autorizado (solo owner)
     * @param minter Dirección del nuevo minter
     */
    function addMinter(address minter) external onlyOwner {
        require(minter != address(0), "CMPX: Minter cannot be zero address");
        require(!minters[minter], "CMPX: Already a minter");

        minters[minter] = true;
        emit MinterAdded(minter);
    }

    /**
     * @notice Remueve un minter autorizado (solo owner)
     * @param minter Dirección del minter a remover
     */
    function removeMinter(address minter) external onlyOwner {
        require(minters[minter], "CMPX: Not a minter");

        minters[minter] = false;
        emit MinterRemoved(minter);
    }

    /**
     * @notice Pausa el contrato en caso de emergencia (solo owner)
     */
    function pause() external onlyOwner {
        _pause();
    }

    /**
     * @notice Despausa el contrato (solo owner)
     */
    function unpause() external onlyOwner {
        _unpause();
    }

    /**
     * @notice Reclama tokens gratuitos para testnet (solo en testnet)
     * @param amount Cantidad de tokens a reclamar (máximo TESTNET_FREE_LIMIT)
     */
    function claimTestnetTokens(uint256 amount) external nonReentrant whenNotPaused {
        require(isTestnet, "CMPX: Not in testnet mode");
        require(amount > 0, "CMPX: Amount must be greater than 0");
        require(!blacklisted[msg.sender], "CMPX: Address is blacklisted");

        uint256 alreadyClaimed = testnetTokensClaimed[msg.sender];
        require(alreadyClaimed + amount <= TESTNET_FREE_LIMIT, "CMPX: Exceeds testnet limit per user");
        require(testnetTokensDistributed + amount <= TESTNET_POOL, "CMPX: Exceeds testnet pool");
        require(totalMinted + amount <= MAX_SUPPLY, "CMPX: Exceeds max supply");

        // Actualizar contadores
        testnetTokensClaimed[msg.sender] = alreadyClaimed + amount;
        testnetTokensDistributed += amount;
        totalMinted += amount;

        // Mintear tokens
        _mint(msg.sender, amount);

        emit TestnetTokensClaimed(msg.sender, amount);
        emit TokensMinted(msg.sender, amount, "Testnet claim");
    }

    /**
     * @notice Reclama tokens diarios para usuarios registrados (1% del pool por día)
     * @param amount Cantidad de tokens a reclamar (máximo DAILY_CLAIM_LIMIT)
     */
    function claimDailyTokens(uint256 amount) external nonReentrant whenNotPaused {
        require(isTestnet, "CMPX: Not in testnet mode");
        require(amount > 0, "CMPX: Amount must be greater than 0");
        require(!blacklisted[msg.sender], "CMPX: Address is blacklisted");

        uint256 currentDay = block.timestamp / 1 days;
        uint256 lastClaimDay = lastDailyClaim[msg.sender];

        // Verificar si es un nuevo día
        if (currentDay > lastClaimDay) {
            // Resetear contador diario
            dailyTokensClaimed[msg.sender] = 0;
            lastDailyClaim[msg.sender] = currentDay;
        }

        uint256 alreadyClaimedToday = dailyTokensClaimed[msg.sender];
        require(alreadyClaimedToday + amount <= DAILY_CLAIM_LIMIT, "CMPX: Exceeds daily limit per user");
        require(testnetTokensDistributed + amount <= TESTNET_POOL, "CMPX: Exceeds testnet pool");
        require(totalMinted + amount <= MAX_SUPPLY, "CMPX: Exceeds max supply");

        // Actualizar contadores
        dailyTokensClaimed[msg.sender] = alreadyClaimedToday + amount;
        testnetTokensDistributed += amount;
        totalMinted += amount;

        // Mintear tokens
        _mint(msg.sender, amount);

        emit DailyTokensClaimed(msg.sender, amount, currentDay);
        emit TokensMinted(msg.sender, amount, "Daily claim");
    }

    /**
     * @notice Cambia el modo testnet (solo owner)
     * @param _isTestnet Nuevo estado del modo testnet
     */
    function setTestnetMode(bool _isTestnet) external onlyOwner {
        isTestnet = _isTestnet;
        emit TestnetModeToggled(_isTestnet);
    }

    /**
     * @notice Mintea tokens de prueba para demos (solo en testnet, solo owner)
     * @param to Dirección destino
     * @param amount Cantidad a mintear
     */
    function mintTestnetTokens(address to, uint256 amount) external onlyOwner nonReentrant whenNotPaused {
        require(isTestnet, "CMPX: Not in testnet mode");
        require(to != address(0), "CMPX: Cannot mint to zero address");
        require(!blacklisted[to], "CMPX: Cannot mint to blacklisted address");
        require(testnetTokensDistributed + amount <= TESTNET_POOL, "CMPX: Exceeds testnet pool");
        require(totalMinted + amount <= MAX_SUPPLY, "CMPX: Exceeds max supply");

        testnetTokensDistributed += amount;
        totalMinted += amount;

        _mint(to, amount);

        emit TokensMinted(to, amount, "Testnet mint by owner");
    }

    /**
     * @notice Retorna la cantidad de tokens disponibles para mint
     * @return uint256 Tokens disponibles
     */
    function remainingSupply() external view returns (uint256) {
        return MAX_SUPPLY - totalMinted;
    }

    /**
     * @notice Verifica si una dirección está en blacklist
     * @param account Dirección a verificar
     * @return bool true si está en blacklist
     */
    function isBlacklisted(address account) external view returns (bool) {
        return blacklisted[account];
    }

    /**
     * @notice Verifica si una dirección es minter autorizado
     * @param account Dirección a verificar
     * @return bool true si es minter autorizado
     */
    function isMinter(address account) external view returns (bool) {
        return minters[account];
    }

    /**
     * @notice Retorna información de testnet para un usuario
     * @param user Dirección del usuario
     * @return claimed Tokens ya reclamados (gratuitos)
     * @return remaining Tokens restantes que puede reclamar (gratuitos)
     * @return dailyClaimed Tokens reclamados hoy (diarios)
     * @return dailyRemaining Tokens restantes hoy (diarios)
     * @return poolRemaining Tokens restantes en el pool de testnet
     */
    function getTestnetInfo(address user) external view returns (
        uint256 claimed,
        uint256 remaining,
        uint256 dailyClaimed,
        uint256 dailyRemaining,
        uint256 poolRemaining
    ) {
        claimed = testnetTokensClaimed[user];
        remaining = TESTNET_FREE_LIMIT > claimed ? TESTNET_FREE_LIMIT - claimed : 0;

        uint256 currentDay = block.timestamp / 1 days;
        uint256 lastClaimDay = lastDailyClaim[user];

        if (currentDay > lastClaimDay) {
            // Nuevo día, puede reclamar el límite completo
            dailyClaimed = 0;
            dailyRemaining = DAILY_CLAIM_LIMIT;
        } else {
            // Mismo día, verificar lo ya reclamado
            dailyClaimed = dailyTokensClaimed[user];
            dailyRemaining = DAILY_CLAIM_LIMIT > dailyClaimed ? DAILY_CLAIM_LIMIT - dailyClaimed : 0;
        }

        poolRemaining = TESTNET_POOL > testnetTokensDistributed ? TESTNET_POOL - testnetTokensDistributed : 0;
    }

    /**
     * @notice Retorna estadísticas generales de testnet
     * @return isTestnetActive Si el modo testnet está activo
     * @return totalDistributed Total de tokens distribuidos en testnet
     * @return poolRemaining Tokens restantes en el pool
     * @return freeLimit Límite de tokens gratuitos por usuario
     * @return dailyLimit Límite diario por usuario registrado (1% del pool)
     */
    function getTestnetStats() external view returns (
        bool isTestnetActive,
        uint256 totalDistributed,
        uint256 poolRemaining,
        uint256 freeLimit,
        uint256 dailyLimit
    ) {
        isTestnetActive = isTestnet;
        totalDistributed = testnetTokensDistributed;
        poolRemaining = TESTNET_POOL > testnetTokensDistributed ? TESTNET_POOL - testnetTokensDistributed : 0;
        freeLimit = TESTNET_FREE_LIMIT;
        dailyLimit = DAILY_CLAIM_LIMIT;
    }
}

contracts/CoupleNFT.sol.content:
// SPDX-License-Identifier: MIT
// ComplicesConecta v3.7.0 - CoupleNFT (ERC-721 con Consentimiento Doble)
// Fecha: 13 Nov 2025 | Autor: Ing. Juan Carlos Méndez Nataren
// Descripción: NFT ERC-721 para parejas con sistema de consentimiento doble obligatorio
// Funcionalidades: Dual mint, consentimiento doble, seguridad extrema, timeout

pragma solidity ^0.8.25;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/token/ERC721/extensions/ERC721URIStorage.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/security/Pausable.sol";
import "@openzeppelin/contracts/utils/Counters.sol";

/**
 * @title CoupleNFT - NFT para Parejas con Consentimiento Doble
 * @dev Contrato ERC-721 que requiere consentimiento de ambas partes para mint
 * @notice Sistema de NFTs para parejas con verificación de consentimiento doble
 * 
 * Características principales:
 * - Consentimiento doble obligatorio
 * - Timeout de 24 horas para aprobación
 * - Dual mint (ambos reciben NFT)
 * - Sistema de cancelación
 * - Blacklist integrada
 * - Metadata IPFS
 */
contract CoupleNFT is ERC721, ERC721URIStorage, Ownable, ReentrancyGuard, Pausable {
    using Counters for Counters.Counter;

    /// @notice Contador de token IDs
    Counters.Counter private _tokenIdCounter;

    /// @notice Timeout para aprobación de consentimiento (24 horas)
    uint256 public constant CONSENT_TIMEOUT = 24 hours;

    /// @notice Costo de mint en CMPX tokens
    uint256 public mintCost = 200 * 10**18; // 200 CMPX

    /// @notice Dirección del contrato CMPX
    address public cmpxToken;

    /**
     * @dev Estructura para almacenar información de consentimiento de pareja
     */
    struct CoupleConsent {
        address partner1;           // Primera pareja
        address partner2;           // Segunda pareja
        uint256 consentTimestamp1;  // Timestamp de consentimiento partner1
        uint256 consentTimestamp2;  // Timestamp de consentimiento partner2
        uint256 requestTimestamp;   // Timestamp de solicitud inicial
        string tokenURI;            // URI del metadata IPFS
        bool isActive;              // Estado activo de la solicitud
        bool isMinted;              // Si ya fue minteado
        address initiator;          // Quien inició la solicitud
    }

    /// @notice Mapping de consentimientos por token ID
    mapping(uint256 => CoupleConsent) public coupleConsents;

    /// @notice Mapping de direcciones en blacklist
    mapping(address => bool) public blacklisted;

    /// @notice Mapping de solicitudes pendientes por usuario
    mapping(address => uint256[]) public pendingRequests;

    /// @notice Mapping de NFTs por pareja (para evitar duplicados)
    mapping(bytes32 => bool) public coupleExists;

    // Eventos personalizados
    event CoupleRequestCreated(
        uint256 indexed tokenId,
        address indexed partner1,
        address indexed partner2,
        address initiator,
        uint256 timestamp
    );

    event ConsentGiven(
        uint256 indexed tokenId,
        address indexed partner,
        uint256 timestamp
    );

    event CoupleNFTMinted(
        uint256 indexed tokenId1,
        uint256 indexed tokenId2,
        address indexed partner1,
        address partner2,
        string tokenURI
    );

    event RequestCancelled(
        uint256 indexed tokenId,
        address indexed canceller,
        string reason
    );

    event AddressBlacklisted(address indexed account, bool status);

    /**
     * @notice Constructor del contrato CoupleNFT
     * @param _cmpxToken Dirección del contrato CMPX
     */
    constructor(address _cmpxToken) 
        ERC721("ComplicesConecta Couple NFT", "CCNFT") 
    {
        require(_cmpxToken != address(0), "CoupleNFT: CMPX token cannot be zero address");
        cmpxToken = _cmpxToken;
    }

    /**
     * @notice Solicita mint de NFT para pareja
     * @param partner1 Dirección de la primera pareja
     * @param partner2 Dirección de la segunda pareja
     * @param _tokenURI URI del metadata IPFS
     * @return uint256 Token ID de la solicitud
     */
    function requestCoupleMint(
        address partner1,
        address partner2,
        string memory _tokenURI
    ) external nonReentrant whenNotPaused returns (uint256) {
        require(partner1 != address(0) && partner2 != address(0), "CoupleNFT: Partners cannot be zero address");
        require(partner1 != partner2, "CoupleNFT: Partners must be different");
        require(msg.sender == partner1 || msg.sender == partner2, "CoupleNFT: Caller must be one of the partners");
        require(!blacklisted[partner1] && !blacklisted[partner2], "CoupleNFT: One or both partners are blacklisted");
        require(bytes(_tokenURI).length > 0, "CoupleNFT: Token URI cannot be empty");

        // Verificar que la pareja no tenga ya un NFT
        bytes32 coupleHash = keccak256(abi.encodePacked(
            partner1 < partner2 ? partner1 : partner2,
            partner1 < partner2 ? partner2 : partner1
        ));
        require(!coupleExists[coupleHash], "CoupleNFT: Couple already has an NFT");

        _tokenIdCounter.increment();
        uint256 tokenId = _tokenIdCounter.current();

        // Crear solicitud de consentimiento
        coupleConsents[tokenId] = CoupleConsent({
            partner1: partner1,
            partner2: partner2,
            consentTimestamp1: msg.sender == partner1 ? block.timestamp : 0,
            consentTimestamp2: msg.sender == partner2 ? block.timestamp : 0,
            requestTimestamp: block.timestamp,
            tokenURI: _tokenURI,
            isActive: true,
            isMinted: false,
            initiator: msg.sender
        });

        // Añadir a solicitudes pendientes
        pendingRequests[partner1].push(tokenId);
        pendingRequests[partner2].push(tokenId);

        emit CoupleRequestCreated(tokenId, partner1, partner2, msg.sender, block.timestamp);

        return tokenId;
    }

    /**
     * @notice Aprueba mint de NFT para pareja
     * @param tokenId ID del token a aprobar
     */
    function approveCoupleMint(uint256 tokenId) external nonReentrant whenNotPaused {
        CoupleConsent storage consent = coupleConsents[tokenId];

        require(consent.isActive, "CoupleNFT: Request is not active");
        require(!consent.isMinted, "CoupleNFT: Already minted");
        require(msg.sender == consent.partner1 || msg.sender == consent.partner2, "CoupleNFT: Not authorized");
        require(!blacklisted[msg.sender], "CoupleNFT: Caller is blacklisted");
        require(block.timestamp <= consent.requestTimestamp + CONSENT_TIMEOUT, "CoupleNFT: Request expired");

        // Registrar consentimiento
        if (msg.sender == consent.partner1 && consent.consentTimestamp1 == 0) {
            consent.consentTimestamp1 = block.timestamp;
            emit ConsentGiven(tokenId, msg.sender, block.timestamp);
        } else if (msg.sender == consent.partner2 && consent.consentTimestamp2 == 0) {
            consent.consentTimestamp2 = block.timestamp;
            emit ConsentGiven(tokenId, msg.sender, block.timestamp);
        } else {
            revert("CoupleNFT: Already consented or not authorized");
        }

        // Si ambos han dado consentimiento, proceder con el mint
        if (consent.consentTimestamp1 > 0 && consent.consentTimestamp2 > 0) {
            _executeDualMint(tokenId);
        }
    }

    /**
     * @notice Ejecuta el mint dual para la pareja
     * @param tokenId ID del token base
     */
    function _executeDualMint(uint256 tokenId) internal {
        CoupleConsent storage consent = coupleConsents[tokenId];

        // Verificar pago en CMPX tokens
        require(_verifyPayment(consent.partner1, consent.partner2), "CoupleNFT: Insufficient CMPX balance");

        // Mint dual NFT
        uint256 tokenId2 = _tokenIdCounter.current() + 1;
        _tokenIdCounter.increment();

        _safeMint(consent.partner1, tokenId);
        _safeMint(consent.partner2, tokenId2);

        _setTokenURI(tokenId, consent.tokenURI);
        _setTokenURI(tokenId2, consent.tokenURI);

        // Marcar como minteado
        consent.isMinted = true;
        consent.isActive = false;

        // Marcar pareja como existente
        bytes32 coupleHash = keccak256(abi.encodePacked(
            consent.partner1 < consent.partner2 ? consent.partner1 : consent.partner2,
            consent.partner1 < consent.partner2 ? consent.partner2 : consent.partner1
        ));
        coupleExists[coupleHash] = true;

        // Limpiar solicitudes pendientes
        _removePendingRequest(consent.partner1, tokenId);
        _removePendingRequest(consent.partner2, tokenId);

        emit CoupleNFTMinted(tokenId, tokenId2, consent.partner1, consent.partner2, consent.tokenURI);
    }

    /**
     * @notice Cancela una solicitud de mint
     * @param tokenId ID del token a cancelar
     * @param reason Razón de la cancelación
     */
    function cancelRequest(uint256 tokenId, string memory reason) external nonReentrant {
        CoupleConsent storage consent = coupleConsents[tokenId];

        require(consent.isActive, "CoupleNFT: Request is not active");
        require(!consent.isMinted, "CoupleNFT: Already minted");
        require(
            msg.sender == consent.partner1 || 
            msg.sender == consent.partner2 || 
            msg.sender == owner(),
            "CoupleNFT: Not authorized to cancel"
        );

        consent.isActive = false;

        // Limpiar solicitudes pendientes
        _removePendingRequest(consent.partner1, tokenId);
        _removePendingRequest(consent.partner2, tokenId);

        emit RequestCancelled(tokenId, msg.sender, reason);
    }

    /**
     * @notice Verifica el pago en tokens CMPX
     * @param partner1 Primera pareja
     * @param partner2 Segunda pareja
     * @return bool Si el pago es válido
     */
    function _verifyPayment(address partner1, address partner2) internal view returns (bool) {
        // Implementar verificación de balance CMPX
        // Por ahora retorna true para testnet
        return true;
    }

    /**
     * @notice Remueve una solicitud pendiente de la lista
     * @param user Usuario
     * @param tokenId Token ID a remover
     */
    function _removePendingRequest(address user, uint256 tokenId) internal {
        uint256[] storage requests = pendingRequests[user];
        for (uint256 i = 0; i < requests.length; i++) {
            if (requests[i] == tokenId) {
                requests[i] = requests[requests.length - 1];
                requests.pop();
                break;
            }
        }
    }

    /**
     * @notice Añade o remueve una dirección de la blacklist (solo owner)
     * @param account Dirección a modificar
     * @param status true para blacklist, false para remover
     */
    function setBlacklist(address account, bool status) external onlyOwner {
        require(account != address(0), "CoupleNFT: Cannot blacklist zero address");
        require(account != owner(), "CoupleNFT: Cannot blacklist owner");

        blacklisted[account] = status;
        emit AddressBlacklisted(account, status);
    }

    /**
     * @notice Actualiza el costo de mint (solo owner)
     * @param newCost Nuevo costo en CMPX tokens
     */
    function setMintCost(uint256 newCost) external onlyOwner {
        require(newCost > 0, "CoupleNFT: Cost must be greater than 0");
        mintCost = newCost;
    }

    /**
     * @notice Pausa el contrato en caso de emergencia (solo owner)
     */
    function pause() external onlyOwner {
        _pause();
    }

    /**
     * @notice Despausa el contrato (solo owner)
     */
    function unpause() external onlyOwner {
        _unpause();
    }

    /**
     * @notice Limpia solicitudes expiradas
     * @param tokenIds Array de token IDs a limpiar
     */
    function cleanupExpiredRequests(uint256[] calldata tokenIds) external {
        for (uint256 i = 0; i < tokenIds.length; i++) {
            uint256 tokenId = tokenIds[i];
            CoupleConsent storage consent = coupleConsents[tokenId];

            if (consent.isActive && 
                !consent.isMinted && 
                block.timestamp > consent.requestTimestamp + CONSENT_TIMEOUT) {

                consent.isActive = false;
                _removePendingRequest(consent.partner1, tokenId);
                _removePendingRequest(consent.partner2, tokenId);

                emit RequestCancelled(tokenId, msg.sender, "Expired");
            }
        }
    }

    /**
     * @notice Retorna las solicitudes pendientes de un usuario
     * @param user Dirección del usuario
     * @return uint256[] Array de token IDs pendientes
     */
    function getPendingRequests(address user) external view returns (uint256[] memory) {
        return pendingRequests[user];
    }

    /**
     * @notice Verifica si una pareja ya tiene un NFT
     * @param partner1 Primera pareja
     * @param partner2 Segunda pareja
     * @return bool Si la pareja ya existe
     */
    function coupleHasNFT(address partner1, address partner2) external view returns (bool) {
        bytes32 coupleHash = keccak256(abi.encodePacked(
            partner1 < partner2 ? partner1 : partner2,
            partner1 < partner2 ? partner2 : partner1
        ));
        return coupleExists[coupleHash];
    }

    // Funciones requeridas por herencia múltiple
    function _burn(uint256 tokenId) internal override(ERC721, ERC721URIStorage) {
        super._burn(tokenId);
    }

    function tokenURI(uint256 tokenId) public view override(ERC721, ERC721URIStorage) returns (string memory) {
        return super.tokenURI(tokenId);
    }

    function supportsInterface(bytes4 interfaceId) public view override(ERC721, ERC721URIStorage) returns (bool) {
        return super.supportsInterface(interfaceId);
    }
}

contracts/StakingPool.sol.content:
// SPDX-License-Identifier: MIT
// ComplicesConecta v3.7.0 - StakingPool (NFT + Token Staking)
// Fecha: 13 Nov 2025 | Autor: Ing. Juan Carlos Méndez Nataren
// Descripción: Pool de staking para NFTs y tokens GTK con rewards en CMPX
// Funcionalidades: NFT staking, token staking, APY 10-20%, vesting, penalizaciones

pragma solidity ^0.8.25;

import "@openzeppelin/contracts/token/ERC721/IERC721.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC721/IERC721Receiver.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/security/Pausable.sol";
import "@openzeppelin/contracts/utils/math/SafeMath.sol";

/**
 * @title StakingPool - Pool de Staking para NFTs y Tokens
 * @dev Contrato para staking de NFTs y tokens GTK con rewards en CMPX
 * @notice Sistema de staking con vesting, APY variable y penalizaciones
 * 
 * Características principales:
 * - Staking de NFTs (ERC-721)
 * - Staking de tokens GTK (ERC-20)
 * - Rewards en tokens CMPX
 * - APY 10-20% según duración
 * - Vesting period mínimo 30 días
 * - Penalización por unstake temprano
 * - Boost por rareza de NFTs
 */
contract StakingPool is Ownable, ReentrancyGuard, Pausable, IERC721Receiver {
    using SafeMath for uint256;

    /// @notice Contrato de NFTs para staking
    IERC721 public nftContract;

    /// @notice Token GTK para staking
    IERC20 public gtkToken;

    /// @notice Token CMPX para rewards
    IERC20 public cmpxToken;

    /// @notice APY base para staking (15%)
    uint256 public constant BASE_APY = 15;

    /// @notice APY máximo para staking (35%)
    uint256 public constant MAX_APY = 35;

    /// @notice Período mínimo de vesting (30 días)
    uint256 public constant MIN_VESTING_PERIOD = 30 days;

    /// @notice Período máximo de vesting (365 días)
    uint256 public constant MAX_VESTING_PERIOD = 365 days;

    /// @notice Penalización por unstake temprano (10%)
    uint256 public constant EARLY_UNSTAKE_PENALTY = 10;

    /// @notice Multiplicador base para cálculos (para evitar decimales)
    uint256 public constant MULTIPLIER = 1e18;

    /**
     * @dev Estructura para información de staking de NFT
     */
    struct NFTStake {
        address owner;              // Propietario del NFT
        uint256 tokenId;           // ID del token NFT
        uint256 stakedAt;          // Timestamp de inicio de staking
        uint256 vestingPeriod;     // Período de vesting elegido
        uint256 lastClaimAt;       // Último claim de rewards
        uint256 rarityMultiplier;  // Multiplicador por rareza (100-200)
        bool isActive;             // Si el stake está activo
    }

    /**
     * @dev Estructura para información de staking de tokens GTK
     */
    struct TokenStake {
        address owner;             // Propietario de los tokens
        uint256 amount;            // Cantidad de tokens stakeados
        uint256 stakedAt;          // Timestamp de inicio de staking
        uint256 vestingPeriod;     // Período de vesting elegido
        uint256 lastClaimAt;       // Último claim de rewards
        bool isActive;             // Si el stake está activo
    }

    /// @notice Mapping de stakes de NFT por token ID
    mapping(uint256 => NFTStake) public nftStakes;

    /// @notice Mapping de stakes de token por usuario y índice
    mapping(address => mapping(uint256 => TokenStake)) public tokenStakes;

    /// @notice Contador de stakes de token por usuario
    mapping(address => uint256) public userTokenStakeCount;

    /// @notice NFTs stakeados por usuario
    mapping(address => uint256[]) public userStakedNFTs;

    /// @notice Total de NFTs stakeados
    uint256 public totalNFTsStaked;

    /// @notice Total de tokens GTK stakeados
    uint256 public totalGTKStaked;

    /// @notice Total de rewards distribuidos
    uint256 public totalRewardsDistributed;

    /// @notice Pool de rewards disponibles
    uint256 public rewardsPool;

    /// @notice Multiplicadores de rareza por tipo de NFT
    mapping(string => uint256) public rarityMultipliers;

    // Eventos
    event NFTStaked(
        address indexed user,
        uint256 indexed tokenId,
        uint256 vestingPeriod,
        uint256 rarityMultiplier,
        uint256 timestamp
    );

    event TokensStaked(
        address indexed user,
        uint256 indexed stakeIndex,
        uint256 amount,
        uint256 vestingPeriod,
        uint256 timestamp
    );

    event NFTUnstaked(
        address indexed user,
        uint256 indexed tokenId,
        uint256 rewards,
        uint256 penalty,
        uint256 timestamp
    );

    event TokensUnstaked(
        address indexed user,
        uint256 indexed stakeIndex,
        uint256 amount,
        uint256 rewards,
        uint256 penalty,
        uint256 timestamp
    );

    event RewardsClaimed(
        address indexed user,
        uint256 amount,
        uint256 timestamp
    );

    event RewardsPoolFunded(
        uint256 amount,
        uint256 timestamp
    );

    /**
     * @notice Constructor del contrato StakingPool
     * @param _nftContract Dirección del contrato NFT
     * @param _gtkToken Dirección del token GTK
     * @param _cmpxToken Dirección del token CMPX
     */
    constructor(
        address _nftContract,
        address _gtkToken,
        address _cmpxToken
    ) {
        require(_nftContract != address(0), "StakingPool: NFT contract cannot be zero address");
        require(_gtkToken != address(0), "StakingPool: GTK token cannot be zero address");
        require(_cmpxToken != address(0), "StakingPool: CMPX token cannot be zero address");

        nftContract = IERC721(_nftContract);
        gtkToken = IERC20(_gtkToken);
        cmpxToken = IERC20(_cmpxToken);

        // Configurar multiplicadores de rareza por defecto
        rarityMultipliers["common"] = 100;    // 1.0x
        rarityMultipliers["rare"] = 125;      // 1.25x
        rarityMultipliers["epic"] = 150;      // 1.5x
        rarityMultipliers["legendary"] = 200; // 2.0x
    }

    /**
     * @notice Stakea un NFT
     * @param tokenId ID del token NFT
     * @param vestingPeriod Período de vesting (30-365 días)
     * @param rarity Rareza del NFT ("common", "rare", "epic", "legendary")
     */
    function stakeNFT(
        uint256 tokenId,
        uint256 vestingPeriod,
        string memory rarity
    ) external nonReentrant whenNotPaused {
        require(vestingPeriod >= MIN_VESTING_PERIOD, "StakingPool: Vesting period too short");
        require(vestingPeriod <= MAX_VESTING_PERIOD, "StakingPool: Vesting period too long");
        require(nftContract.ownerOf(tokenId) == msg.sender, "StakingPool: Not owner of NFT");
        require(!nftStakes[tokenId].isActive, "StakingPool: NFT already staked");
        require(rarityMultipliers[rarity] > 0, "StakingPool: Invalid rarity");

        // Transferir NFT al contrato
        nftContract.safeTransferFrom(msg.sender, address(this), tokenId);

        // Crear stake
        nftStakes[tokenId] = NFTStake({
            owner: msg.sender,
            tokenId: tokenId,
            stakedAt: block.timestamp,
            vestingPeriod: vestingPeriod,
            lastClaimAt: block.timestamp,
            rarityMultiplier: rarityMultipliers[rarity],
            isActive: true
        });

        // Actualizar contadores
        userStakedNFTs[msg.sender].push(tokenId);
        totalNFTsStaked = totalNFTsStaked.add(1);

        emit NFTStaked(msg.sender, tokenId, vestingPeriod, rarityMultipliers[rarity], block.timestamp);
    }

    /**
     * @notice Stakea tokens GTK
     * @param amount Cantidad de tokens a stakear
     * @param vestingPeriod Período de vesting (30-365 días)
     */
    function stakeTokens(
        uint256 amount,
        uint256 vestingPeriod
    ) external nonReentrant whenNotPaused {
        require(amount > 0, "StakingPool: Amount must be greater than 0");
        require(vestingPeriod >= MIN_VESTING_PERIOD, "StakingPool: Vesting period too short");
        require(vestingPeriod <= MAX_VESTING_PERIOD, "StakingPool: Vesting period too long");
        require(gtkToken.balanceOf(msg.sender) >= amount, "StakingPool: Insufficient GTK balance");

        // Transferir tokens al contrato
        require(gtkToken.transferFrom(msg.sender, address(this), amount), "StakingPool: Transfer failed");

        // Crear stake
        uint256 stakeIndex = userTokenStakeCount[msg.sender];
        tokenStakes[msg.sender][stakeIndex] = TokenStake({
            owner: msg.sender,
            amount: amount,
            stakedAt: block.timestamp,
            vestingPeriod: vestingPeriod,
            lastClaimAt: block.timestamp,
            isActive: true
        });

        // Actualizar contadores
        userTokenStakeCount[msg.sender] = userTokenStakeCount[msg.sender].add(1);
        totalGTKStaked = totalGTKStaked.add(amount);

        emit TokensStaked(msg.sender, stakeIndex, amount, vestingPeriod, block.timestamp);
    }

    /**
     * @notice Unstakea un NFT
     * @param tokenId ID del token NFT
     */
    function unstakeNFT(uint256 tokenId) external nonReentrant whenNotPaused {
        NFTStake storage stake = nftStakes[tokenId];
        require(stake.isActive, "StakingPool: NFT not staked");
        require(stake.owner == msg.sender, "StakingPool: Not owner of stake");

        // Calcular rewards
        uint256 rewards = calculateNFTRewards(tokenId);
        uint256 penalty = 0;

        // Verificar si es unstake temprano
        if (block.timestamp < stake.stakedAt.add(stake.vestingPeriod)) {
            penalty = rewards.mul(EARLY_UNSTAKE_PENALTY).div(100);
            rewards = rewards.sub(penalty);
        }

        // Marcar como inactivo
        stake.isActive = false;

        // Remover de la lista del usuario
        _removeNFTFromUserList(msg.sender, tokenId);

        // Actualizar contadores
        totalNFTsStaked = totalNFTsStaked.sub(1);

        // Transferir NFT de vuelta
        nftContract.safeTransferFrom(address(this), msg.sender, tokenId);

        // Transferir rewards si hay disponibles
        if (rewards > 0 && rewardsPool >= rewards) {
            rewardsPool = rewardsPool.sub(rewards);
            totalRewardsDistributed = totalRewardsDistributed.add(rewards);
            require(cmpxToken.transfer(msg.sender, rewards), "StakingPool: Reward transfer failed");
        }

        emit NFTUnstaked(msg.sender, tokenId, rewards, penalty, block.timestamp);
    }

    /**
     * @notice Unstakea tokens GTK
     * @param stakeIndex Índice del stake
     */
    function unstakeTokens(uint256 stakeIndex) external nonReentrant whenNotPaused {
        TokenStake storage stake = tokenStakes[msg.sender][stakeIndex];
        require(stake.isActive, "StakingPool: Tokens not staked");
        require(stake.owner == msg.sender, "StakingPool: Not owner of stake");

        // Calcular rewards
        uint256 rewards = calculateTokenRewards(msg.sender, stakeIndex);
        uint256 penalty = 0;

        // Verificar si es unstake temprano
        if (block.timestamp < stake.stakedAt.add(stake.vestingPeriod)) {
            penalty = rewards.mul(EARLY_UNSTAKE_PENALTY).div(100);
            rewards = rewards.sub(penalty);
        }

        uint256 stakedAmount = stake.amount;

        // Marcar como inactivo
        stake.isActive = false;

        // Actualizar contadores
        totalGTKStaked = totalGTKStaked.sub(stakedAmount);

        // Transferir tokens de vuelta
        require(gtkToken.transfer(msg.sender, stakedAmount), "StakingPool: Token transfer failed");

        // Transferir rewards si hay disponibles
        if (rewards > 0 && rewardsPool >= rewards) {
            rewardsPool = rewardsPool.sub(rewards);
            totalRewardsDistributed = totalRewardsDistributed.add(rewards);
            require(cmpxToken.transfer(msg.sender, rewards), "StakingPool: Reward transfer failed");
        }

        emit TokensUnstaked(msg.sender, stakeIndex, stakedAmount, rewards, penalty, block.timestamp);
    }

    /**
     * @notice Reclama rewards de NFT sin unstakear
     * @param tokenId ID del token NFT
     */
    function claimNFTRewards(uint256 tokenId) external nonReentrant whenNotPaused {
        NFTStake storage stake = nftStakes[tokenId];
        require(stake.isActive, "StakingPool: NFT not staked");
        require(stake.owner == msg.sender, "StakingPool: Not owner of stake");

        uint256 rewards = calculateNFTRewards(tokenId);
        require(rewards > 0, "StakingPool: No rewards available");
        require(rewardsPool >= rewards, "StakingPool: Insufficient rewards pool");

        // Actualizar último claim
        stake.lastClaimAt = block.timestamp;

        // Transferir rewards
        rewardsPool = rewardsPool.sub(rewards);
        totalRewardsDistributed = totalRewardsDistributed.add(rewards);
        require(cmpxToken.transfer(msg.sender, rewards), "StakingPool: Reward transfer failed");

        emit RewardsClaimed(msg.sender, rewards, block.timestamp);
    }

    /**
     * @notice Reclama rewards de tokens sin unstakear
     * @param stakeIndex Índice del stake
     */
    function claimTokenRewards(uint256 stakeIndex) external nonReentrant whenNotPaused {
        TokenStake storage stake = tokenStakes[msg.sender][stakeIndex];
        require(stake.isActive, "StakingPool: Tokens not staked");
        require(stake.owner == msg.sender, "StakingPool: Not owner of stake");

        uint256 rewards = calculateTokenRewards(msg.sender, stakeIndex);
        require(rewards > 0, "StakingPool: No rewards available");
        require(rewardsPool >= rewards, "StakingPool: Insufficient rewards pool");

        // Actualizar último claim
        stake.lastClaimAt = block.timestamp;

        // Transferir rewards
        rewardsPool = rewardsPool.sub(rewards);
        totalRewardsDistributed = totalRewardsDistributed.add(rewards);
        require(cmpxToken.transfer(msg.sender, rewards), "StakingPool: Reward transfer failed");

        emit RewardsClaimed(msg.sender, rewards, block.timestamp);
    }

    /**
     * @notice Calcula rewards pendientes para un NFT
     * @param tokenId ID del token NFT
     * @return uint256 Cantidad de rewards pendientes
     */
    function calculateNFTRewards(uint256 tokenId) public view returns (uint256) {
        NFTStake storage stake = nftStakes[tokenId];
        if (!stake.isActive) return 0;

        uint256 timeStaked = block.timestamp.sub(stake.lastClaimAt);
        uint256 apy = _calculateAPY(stake.vestingPeriod);

        // Base reward: 1 NFT = 100 CMPX base por año
        uint256 baseReward = 100 * MULTIPLIER;
        uint256 yearlyReward = baseReward.mul(apy).div(100);
        uint256 rewards = yearlyReward.mul(timeStaked).div(365 days);

        // Aplicar multiplicador de rareza
        rewards = rewards.mul(stake.rarityMultiplier).div(100);

        return rewards;
    }

    /**
     * @notice Calcula rewards pendientes para tokens
     * @param user Dirección del usuario
     * @param stakeIndex Índice del stake
     * @return uint256 Cantidad de rewards pendientes
     */
    function calculateTokenRewards(address user, uint256 stakeIndex) public view returns (uint256) {
        TokenStake storage stake = tokenStakes[user][stakeIndex];
        if (!stake.isActive) return 0;

        uint256 timeStaked = block.timestamp.sub(stake.lastClaimAt);
        uint256 apy = _calculateAPY(stake.vestingPeriod);

        uint256 yearlyReward = stake.amount.mul(apy).div(100);
        uint256 rewards = yearlyReward.mul(timeStaked).div(365 days);

        return rewards;
    }

    /**
     * @notice Calcula APY basado en el período de vesting
     * @param vestingPeriod Período de vesting
     * @return uint256 APY calculado
     */
    function _calculateAPY(uint256 vestingPeriod) internal pure returns (uint256) {
        if (vestingPeriod >= MAX_VESTING_PERIOD) {
            return MAX_APY; // 35% APY para 365 días
        } else if (vestingPeriod >= 270 days) {
            return 30; // 30% APY para 270 días (9 meses)
        } else if (vestingPeriod >= 180 days) {
            return 25; // 25% APY para 180 días (6 meses)
        } else if (vestingPeriod >= 90 days) {
            return 20; // 20% APY para 90 días (3 meses)
        } else {
            return BASE_APY; // 15% APY para 30 días (1 mes)
        }
    }

    /**
     * @notice Remueve un NFT de la lista del usuario
     * @param user Usuario
     * @param tokenId Token ID a remover
     */
    function _removeNFTFromUserList(address user, uint256 tokenId) internal {
        uint256[] storage userNFTs = userStakedNFTs[user];
        for (uint256 i = 0; i < userNFTs.length; i++) {
            if (userNFTs[i] == tokenId) {
                userNFTs[i] = userNFTs[userNFTs.length - 1];
                userNFTs.pop();
                break;
            }
        }
    }

    /**
     * @notice Financia el pool de rewards (solo owner)
     * @param amount Cantidad de CMPX a añadir
     */
    function fundRewardsPool(uint256 amount) external onlyOwner {
        require(amount > 0, "StakingPool: Amount must be greater than 0");
        require(cmpxToken.transferFrom(msg.sender, address(this), amount), "StakingPool: Transfer failed");

        rewardsPool = rewardsPool.add(amount);
        emit RewardsPoolFunded(amount, block.timestamp);
    }

    /**
     * @notice Actualiza multiplicador de rareza (solo owner)
     * @param rarity Tipo de rareza
     * @param multiplier Nuevo multiplicador
     */
    function setRarityMultiplier(string memory rarity, uint256 multiplier) external onlyOwner {
        require(multiplier >= 100 && multiplier <= 300, "StakingPool: Invalid multiplier range");
        rarityMultipliers[rarity] = multiplier;
    }

    /**
     * @notice Retorna NFTs stakeados por usuario
     * @param user Dirección del usuario
     * @return uint256[] Array de token IDs
     */
    function getUserStakedNFTs(address user) external view returns (uint256[] memory) {
        return userStakedNFTs[user];
    }

    /**
     * @notice Pausa el contrato (solo owner)
     */
    function pause() external onlyOwner {
        _pause();
    }

    /**
     * @notice Despausa el contrato (solo owner)
     */
    function unpause() external onlyOwner {
        _unpause();
    }

    /**
     * @notice Maneja la recepción de NFTs
     */
    function onERC721Received(
        address operator,
        address from,
        uint256 tokenId,
        bytes calldata data
    ) external pure override returns (bytes4) {
        return IERC721Receiver.onERC721Received.selector;
    }
}

